-- Saída web 2025: preserva congelamento 80; acrescenta volume anual da base conhecida.
-- Não altera valores históricos, comparativos anteriores ou a edição 2026.
WITH anterior AS(SELECT result->'rows'->0->'payload' AS payload FROM estudo.notebook_runs WHERE id=80 AND frozen AND status='ok' AND NOT truncated),
volume AS(SELECT r FROM estudo.notebook_runs n CROSS JOIN LATERAL jsonb_array_elements(n.result->'rows') r WHERE n.id=83 AND n.frozen AND n.status='ok' AND NOT n.truncated AND n.cell_id=292 AND n.cell_version=1 AND n.row_count=3),
m AS(
 SELECT 'volume_anual' AS serie,r->>'ano' AS categoria,r->'resultados' AS valor,r->'resultados' AS contagem,NULL::jsonb AS denominador FROM volume
 UNION ALL SELECT 'eventos_anuais_cadastrados',r->>'ano',r->'cadastradas',r->'cadastradas',NULL::jsonb FROM volume
 UNION ALL SELECT 'eventos_anuais_coletados',r->>'ano',r->'coletadas',r->'coletadas',NULL::jsonb FROM volume
 UNION ALL SELECT 'eventos_anuais_elegiveis',r->>'ano',r->'eventos_elegiveis',r->'eventos_elegiveis',NULL::jsonb FROM volume
 UNION ALL SELECT 'variacao_volume_anual',r->>'ano',r->'variacao_percentual',r->'resultados',r->'resultados_ano_anterior' FROM volume WHERE r->>'variacao_percentual' IS NOT NULL
),novas AS(SELECT jsonb_build_object('serie',serie,'categoria',categoria,'status','notebook_em_conciliacao','atual',jsonb_build_object('valor',valor,'contagem',contagem,'fonte','Notebook · #83 · célula 292 rev1 · 01/10/2026','nota',CASE WHEN serie='variacao_volume_anual' THEN 'Variação relativa ao total elegível do ano anterior na mesma coleta; não é crescimento do mercado' ELSE 'Ano completo; população e coleta próprias deste bloco' END)||CASE WHEN denominador IS NOT NULL THEN jsonb_build_object('denominador',denominador) ELSE '{}'::jsonb END) AS item FROM m),
comps AS(SELECT x AS item FROM anterior CROSS JOIN LATERAL jsonb_array_elements(payload->'comparacoes') x UNION ALL SELECT item FROM novas)
SELECT payload||jsonb_build_object(
 'meta',payload->'meta'||jsonb_build_object('contrato_versao',4,'notebook_fontes',(payload->'meta'->'notebook_fontes')||(SELECT jsonb_agg(jsonb_build_object('execucao',id,'celula',cell_id,'revisao',cell_version,'coletado_em',started_at)) FROM estudo.notebook_runs WHERE id=83 AND frozen)),
 'series',(payload->'series')||'[{"pagina_pdf": 3, "status": "disponivel_apenas_no_recalculo", "valores": [], "filtros": {}, "casas_decimais": 0, "ressalva": "Coleta própria de 01/10/2026 às 00h05, célula 292 rev1, congelamento 83. Anos completos 2023–2025, país BR, ano pela data final, todas as modalidades e idades. Resultados: status_final=0 e homologado=true, mesma regra da definição atual conferida de vw_resultados; sem filtro adicional de conclusão ou idade 14+. Participações não são atletas únicos. Cadastradas: todos os eventos do calendário, inclusive inativos/cancelados; coletadas: ao menos uma linha bruta; elegíveis: ao menos um resultado que entra na regra. Agregação por evento, sem multiplicação. Variação é da base conhecida, sujeita a importações, revisões e maturação diferentes; não estima crescimento do mercado nem a cobertura de 84,1%. Outros blocos mantêm seus congelamentos próprios; o panorama 2025 conserva 5.279.415 resultados e 9.360 eventos anteriores. Valores históricos exatos do volume permanecem pendentes; esta série não acrescenta valores ao PDF.", "id": "volume_anual", "unidade": "participacoes"}, {"pagina_pdf": 3, "status": "disponivel_apenas_no_recalculo", "valores": [], "filtros": {}, "casas_decimais": 0, "ressalva": "Coleta própria de 01/10/2026 às 00h05, célula 292 rev1, congelamento 83. Anos completos 2023–2025, país BR, ano pela data final, todas as modalidades e idades. Resultados: status_final=0 e homologado=true, mesma regra da definição atual conferida de vw_resultados; sem filtro adicional de conclusão ou idade 14+. Participações não são atletas únicos. Cadastradas: todos os eventos do calendário, inclusive inativos/cancelados; coletadas: ao menos uma linha bruta; elegíveis: ao menos um resultado que entra na regra. Agregação por evento, sem multiplicação. Variação é da base conhecida, sujeita a importações, revisões e maturação diferentes; não estima crescimento do mercado nem a cobertura de 84,1%. Outros blocos mantêm seus congelamentos próprios; o panorama 2025 conserva 5.279.415 resultados e 9.360 eventos anteriores. Valores históricos exatos do volume permanecem pendentes; esta série não acrescenta valores ao PDF.", "id": "eventos_anuais_cadastrados", "unidade": "provas"}, {"pagina_pdf": 3, "status": "disponivel_apenas_no_recalculo", "valores": [], "filtros": {}, "casas_decimais": 0, "ressalva": "Coleta própria de 01/10/2026 às 00h05, célula 292 rev1, congelamento 83. Anos completos 2023–2025, país BR, ano pela data final, todas as modalidades e idades. Resultados: status_final=0 e homologado=true, mesma regra da definição atual conferida de vw_resultados; sem filtro adicional de conclusão ou idade 14+. Participações não são atletas únicos. Cadastradas: todos os eventos do calendário, inclusive inativos/cancelados; coletadas: ao menos uma linha bruta; elegíveis: ao menos um resultado que entra na regra. Agregação por evento, sem multiplicação. Variação é da base conhecida, sujeita a importações, revisões e maturação diferentes; não estima crescimento do mercado nem a cobertura de 84,1%. Outros blocos mantêm seus congelamentos próprios; o panorama 2025 conserva 5.279.415 resultados e 9.360 eventos anteriores. Valores históricos exatos do volume permanecem pendentes; esta série não acrescenta valores ao PDF.", "id": "eventos_anuais_coletados", "unidade": "provas"}, {"pagina_pdf": 3, "status": "disponivel_apenas_no_recalculo", "valores": [], "filtros": {}, "casas_decimais": 0, "ressalva": "Coleta própria de 01/10/2026 às 00h05, célula 292 rev1, congelamento 83. Anos completos 2023–2025, país BR, ano pela data final, todas as modalidades e idades. Resultados: status_final=0 e homologado=true, mesma regra da definição atual conferida de vw_resultados; sem filtro adicional de conclusão ou idade 14+. Participações não são atletas únicos. Cadastradas: todos os eventos do calendário, inclusive inativos/cancelados; coletadas: ao menos uma linha bruta; elegíveis: ao menos um resultado que entra na regra. Agregação por evento, sem multiplicação. Variação é da base conhecida, sujeita a importações, revisões e maturação diferentes; não estima crescimento do mercado nem a cobertura de 84,1%. Outros blocos mantêm seus congelamentos próprios; o panorama 2025 conserva 5.279.415 resultados e 9.360 eventos anteriores. Valores históricos exatos do volume permanecem pendentes; esta série não acrescenta valores ao PDF.", "id": "eventos_anuais_elegiveis", "unidade": "provas"}, {"pagina_pdf": 3, "status": "disponivel_apenas_no_recalculo", "valores": [], "filtros": {}, "casas_decimais": 2, "ressalva": "Coleta própria de 01/10/2026 às 00h05, célula 292 rev1, congelamento 83. Anos completos 2023–2025, país BR, ano pela data final, todas as modalidades e idades. Resultados: status_final=0 e homologado=true, mesma regra da definição atual conferida de vw_resultados; sem filtro adicional de conclusão ou idade 14+. Participações não são atletas únicos. Cadastradas: todos os eventos do calendário, inclusive inativos/cancelados; coletadas: ao menos uma linha bruta; elegíveis: ao menos um resultado que entra na regra. Agregação por evento, sem multiplicação. Variação é da base conhecida, sujeita a importações, revisões e maturação diferentes; não estima crescimento do mercado nem a cobertura de 84,1%. Outros blocos mantêm seus congelamentos próprios; o panorama 2025 conserva 5.279.415 resultados e 9.360 eventos anteriores. Valores históricos exatos do volume permanecem pendentes; esta série não acrescenta valores ao PDF.", "id": "variacao_volume_anual", "unidade": "percentual"}]'::jsonb,
 'comparacoes',(payload->'comparacoes')||(SELECT jsonb_agg(item ORDER BY item->>'serie',item->>'categoria') FROM novas),
 'conciliacao',jsonb_build_object('compativel_no_valor',0,'divergente',0,'nao_recalculado',0,'compativel_no_arredondamento',0,'notebook_em_conciliacao',0)||(SELECT jsonb_object_agg(status,total) FROM(SELECT item->>'status' AS status,count(*) AS total FROM comps GROUP BY 1) q)) AS payload
FROM anterior
WHERE(SELECT count(*) FROM volume)=3 AND(SELECT count(DISTINCT r->>'ano') FROM volume)=3
AND NOT EXISTS(SELECT 1 FROM volume WHERE r->>'ano' NOT IN('2023','2024','2025') OR (r->>'resultados')::bigint<>(r->>'controle_soma')::bigint OR (r->>'resultados_brutos')::bigint<>(r->>'resultados')::bigint+(r->>'resultados_fora_view')::bigint OR (r->>'coletadas')::bigint>(r->>'cadastradas')::bigint OR (r->>'eventos_elegiveis')::bigint>(r->>'coletadas')::bigint)
AND NOT EXISTS(SELECT 1 FROM anterior CROSS JOIN LATERAL jsonb_array_elements(payload->'series') s WHERE s->>'id' IN('volume_anual','eventos_anuais_cadastrados','eventos_anuais_coletados','eventos_anuais_elegiveis','variacao_volume_anual'));
